[CmdletBinding()]
param([switch]$All,[switch]$Client,[switch]$Server,[switch]$ServerAdmin,[switch]$ScreenMedia,[switch]$Updater,[string]$DependencyRoot,[switch]$CacheCandidate,[switch]$DirectCacheCandidate,[string]$ValidationDirectory)
$ErrorActionPreference='Stop'
$root=$PSScriptRoot
if(-not($All-or$Client-or$Server-or$ServerAdmin-or$ScreenMedia-or$Updater)){$All=$true}
