if($ServerAdmin){$Server=$true}
function Run([string]$Name,[scriptblock]$Block){& $Block;if($LASTEXITCODE -ne 0){throw "$Name failed (exit $LASTEXITCODE)."}}
function Need([string]$Path){if(-not(Test-Path -LiteralPath $Path)){throw "Required file is missing: $Path"}}
Push-Location $root
try {
 $sourceVersion=(Select-String -LiteralPath '.\shared\VersionInfo.cs' -Pattern 'Display="([^"]+)"').Matches[0].Groups[1].Value
 if($sourceVersion -notmatch '^(?<base>\d+\.\d+\.\d+-dev)(?:\.\d+)?$'){throw "Expected a development base version in VersionInfo.cs; found '$sourceVersion'."}
 $baseVersion=$Matches['base'];$developmentRoot=Join-Path $root 'build\development';$evaluationRoot=Join-Path $root 'build\evaluation';$outputRoot=$developmentRoot;New-Item -ItemType Directory -Force -Path $outputRoot|Out-Null
 $revisionPattern='^'+[regex]::Escape($baseVersion)+'\.(\d+)$'
 $revisions=@(@($developmentRoot,$evaluationRoot) | Where-Object {Test-Path -LiteralPath $_} | ForEach-Object {Get-ChildItem -LiteralPath $_ -Directory} | ForEach-Object {if($_.Name -match $revisionPattern){[int]$Matches[1]}})
 $nextRevision=[int]($sourceVersion.Split('.')[-1]);if($revisions.Count){$nextRevision=[Math]::Max($nextRevision,([int](($revisions|Measure-Object -Maximum).Maximum))+1)}
 if($ValidationDirectory){
  # Integration validation must not allocate a release revision or overwrite an
