 $fx=Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319';$frameworkCsc=Join-Path $fx 'csc.exe';$roslyn=Join-Path ${env:ProgramFiles} 'Microsoft Visual Studio\18\Community\MSBuild\Current\Bin\Roslyn\csc.exe';$csc=if(Test-Path -LiteralPath $roslyn){$roslyn}else{$frameworkCsc}
 if($Updater){New-Item -ItemType Directory -Force -Path $updaterOut|Out-Null;$r=@('System.dll','System.Core.dll','System.Net.Http.dll','System.Web.Extensions.dll','System.IO.Compression.dll','System.IO.Compression.FileSystem.dll')|%{'/reference:'+(Join-Path $fx $_)};Run 'Updater core' {& $csc /nologo /target:library /platform:anycpu /optimize+ "/out:$updaterOut\PeerChat.Updater.Core.dll" $r $generatedVersionSource .\updater\UpdateModels.cs .\updater\UpdateSecurity.cs .\updater\UpdateDownload.cs .\updater\UpdateCoordinator.cs .\updater\UpdateInstaller.cs};Run 'Updater' {& $csc /nologo /target:exe /platform:anycpu /optimize+ "/out:$updaterOut\PeerChat.Updater.exe" "/reference:$updaterOut\PeerChat.Updater.Core.dll" .\updater\Program.cs};Copy-Item .\updater\PeerChat.Updater.exe.config $updaterOut -Force}
