 if($ScreenMedia){New-Item -ItemType Directory -Force -Path $screenOut|Out-Null;$vswhere=Join-Path ${env:ProgramFiles(x86)} 'Microsoft Visual Studio\Installer\vswhere.exe';$install=&$vswhere -latest -products '*' -requires Microsoft.VisualStudio.Component.VC.Tools.x86.x64 -property installationPath;$sdk=(Get-ChildItem (Join-Path ${env:ProgramFiles(x86)} 'Windows Kits\10\Include') -Directory|Sort-Object Name -Descending|Select-Object -First 1).FullName;$cmd='"{0}" -arch=x64 -host_arch=x64 >nul && cl /nologo /std:c++20 /EHsc /MT /W4 /LD /I"{1}" /Fe:"{2}\PeerChat.ScreenMedia.dll" "{3}" "{4}" "{5}" /link windowsapp.lib d3d11.lib dxgi.lib dwmapi.lib mfplat.lib mfuuid.lib user32.lib gdi32.lib' -f (Join-Path $install 'Common7\Tools\VsDevCmd.bat'),(Join-Path $sdk 'cppwinrt'),$screenOut,'.\windows_media\peerchat_screen_media.cpp','.\windows_media\screen_encoder.cpp','.\windows_media\screen_decoder.cpp';Run 'ScreenMedia' {&cmd /d /c $cmd}}
 [string[]]$cacheDefine=@(if($CacheCandidate){'/define:PEERCHAT_CACHE_CANDIDATE'};if($DirectCacheCandidate){'/define:PEERCHAT_DM_CACHE_CANDIDATE'})
 if($Server){New-Item -ItemType Directory -Force -Path $serverOut|Out-Null;Run 'Server' {&$csc @cacheDefine /nologo /target:exe /platform:x64 /optimize+ "/out:$serverOut\PeerChat.Server.exe" /win32icon:desktop\Assets\Icons\peerchat-server.ico "/reference:$fx\System.Web.Extensions.dll" $generatedVersionSource (Get-ChildItem .\server\AttachmentCache*.cs | ForEach-Object FullName) .\server\ServerConfiguration.cs .\server\GroupRosterProof.cs .\server\ArchiveAuthorization.cs .\server\GroupCiphertextFanout.cs .\server\GroupMediaRooms.cs .\server\ServerPresence.cs .\server\ServerRpc.cs .\server\PeerChat.Server.cs .\server\MailboxProtocol.cs .\server\EncryptedMailbox.cs .\server\EncryptedMailboxChannel.cs};Copy-Item .\desktop\Assets\Icons\peerchat-server.ico $serverOut -Force}
 if($Server){Copy-Item .\server\PeerChat.Server.exe.config $serverOut -Force}
 if($ServerAdmin){New-Item -ItemType Directory -Force -Path $adminOut|Out-Null;$r=@('System.dll','System.Core.dll','System.Xaml.dll','System.Web.Extensions.dll','WPF\WindowsBase.dll','WPF\PresentationCore.dll','WPF\PresentationFramework.dll')|%{'/reference:'+(Join-Path $fx $_)};Run 'ServerAdmin' {&$csc /nologo /target:winexe /platform:x64 /optimize+ "/out:$adminOut\PeerChat.Server.Admin.exe" /win32icon:desktop\Assets\Icons\peerchat-server.ico $r $generatedVersionSource .\server\ServerConfiguration.cs .\server\PeerChat.Server.Admin.cs};Copy-Item .\desktop\Assets\Icons\peerchat-server.ico $adminOut -Force;if($Server){Copy-Item "$serverOut\PeerChat.Server.exe" $adminOut -Force;Copy-Item "$serverOut\PeerChat.Server.exe.config" $adminOut -Force}}
 if($Client){
  $receive='C:\Peerchatdep\build\apm\webrtc-6cf6bcb-presets\x64\PeerChat.AudioReceive.dll';Need $receive
  if((Get-FileHash $receive -Algorithm SHA256).Hash -ne '82621EF0C83C6F4844DF0871FE05D7E637F0287179B94CC19CDF272C9DB40C01'){throw 'AudioReceive hash mismatch.'}
  Copy-Item $receive $clientOut -Force
  if($All){New-Item -ItemType Directory -Force -Path $packageOut|Out-Null;Copy-Item $receive $packageOut -Force}
 }
 if($All){New-Item -ItemType Directory -Force -Path $packageOut|Out-Null;@('PeerChat.Hpke.dll','PeerChat.Desktop.exe','PeerChat.Core.dll','PeerChat.Desktop.exe.config','peerchat-client.ico','PeerChat.Updater.Core.dll','PeerChat.Updater.exe','PeerChat.Updater.exe.config')|%{Copy-Item "$clientOut\$_" $packageOut -Force};Copy-Item "$screenOut\PeerChat.ScreenMedia.dll" $packageOut -Force;Copy-Item "$clientOut\licenses" $packageOut -Recurse -Force;$apm='C:\Peerchatdep\artifacts\audio-processing\webrtc-6cf6bcb-voice-presets\x64\PeerChat.AudioProcessing.dll';Need $apm;if((Get-FileHash $apm -Algorithm SHA256).Hash -ne 'C324896121259FBCE10C6B8B15995606378CF281EEDD7515F0B4680181A75A08'){throw 'APM hash mismatch.'};Copy-Item $apm $packageOut -Force;Copy-Item .\desktop\service-bootstrap.json $packageOut -Force;Copy-Item .\updater\update-feeds.json $packageOut -Force;& .\scripts\verify-client-native-dependencies.ps1 -ClientDirectory $packageOut -RequireScreenMedia -RequireHpke;if($LASTEXITCODE -ne 0){throw 'Package dependency audit failed.'}}
 if($Client){$apm='C:\Peerchatdep\artifacts\audio-processing\webrtc-6cf6bcb-voice-presets\x64\PeerChat.AudioProcessing.dll';Need $apm;if((Get-FileHash $apm -Algorithm SHA256).Hash -ne 'C324896121259FBCE10C6B8B15995606378CF281EEDD7515F0B4680181A75A08'){throw 'APM hash mismatch.'};Copy-Item $apm $clientOut -Force}

 Write-Host "PASS: PeerChat $version development build: $out"
} finally {Pop-Location}
